function validate(input) {
  const [{ Inventory = [] }] = input;
  const ids = new Set(), items = { prime_eligible: 0, not_prime: 0 }, cents = { prime_eligible: 0, not_prime: 0 };
  for (const [id, type, , footage] of Inventory) {
    if (id === null) return 'Every item needs an item_id.';
    if (ids.has(id)) return `item_id ${id} appears twice.`;
    ids.add(id);
    if (type !== 'prime_eligible' && type !== 'not_prime') return `item_type must be prime_eligible or not_prime, not ${type}.`;
    if (footage === null || footage <= 0) return `Item ${id} needs a positive square_footage.`;
    items[type]++;
    cents[type] += Math.round(footage * 100);
  }
  if (!items.prime_eligible || !items.not_prime) return 'Both item types must appear at least once.';
  // Whole batches, counted in hundredths of a square foot so the arithmetic is exact.
  const space = 50000000, primeBatches = Math.floor(space / cents.prime_eligible);
  const otherBatches = Math.floor((space - primeBatches * cents.prime_eligible) / cents.not_prime);
  if (primeBatches * items.prime_eligible <= otherBatches * items.not_prime) return 'More prime_eligible items than not_prime items must be stocked.';
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const categories = ['Watches', 'Art', 'Software', 'Clothing', 'Shoes', 'Scientific', 'Furniture', 'Beauty', 'Food', 'Toys'];
  const space = 50000000;
  // Footage is drawn in hundredths; batch counts are checked exactly so the two counts differ in the right order
  // and no division lands exactly on a whole number (where rounding of stored decimals could tip FLOOR).
  const build = () => {
    const rows = [], used = new Set();
    const id = () => { let v; do v = 1000 + pick(9000); while (used.has(v)); used.add(v); return v; };
    let primeN, otherN, primeCents, otherCents;
    if (size === 'small') {
      primeN = 1 + pick(4); otherN = 1 + pick(4);
      const bulky = rand() < 0.4;
      primeCents = Array.from({ length: primeN }, () => bulky ? 1000000 + pick(15000000) : 500 + pick(40000));
      otherCents = Array.from({ length: otherN }, () => rand() < 0.5 ? 100 + pick(5000) : 500 + pick(40000));
    } else {
      primeN = 1000 + pick(400); otherN = 300 + pick(200);
      primeCents = Array.from({ length: primeN }, () => 1000 + pick(19000));
      otherCents = Array.from({ length: otherN }, () => 1000 + pick(19000));
    }
    const pa = primeCents.reduce((a, b) => a + b, 0), oa = otherCents.reduce((a, b) => a + b, 0);
    const pb = Math.floor(space / pa), rest = space - pb * pa, ob = Math.floor(rest / oa);
    if (space % pa === 0 || rest % oa === 0 || pb * primeN <= ob * otherN) return null;
    for (const c of primeCents) rows.push([id(), 'prime_eligible', categories[pick(categories.length)], c / 100]);
    for (const c of otherCents) rows.push([id(), 'not_prime', categories[pick(categories.length)], c / 100]);
    for (let i = rows.length - 1; i > 0; i--) { const j = pick(i + 1); [rows[i], rows[j]] = [rows[j], rows[i]]; }
    return rows;
  };
  let Inventory = null;
  for (let tries = 0; !Inventory && tries < 50; tries++) Inventory = build();
  if (!Inventory) Inventory = [[1, 'prime_eligible', 'Food', 120.5], [2, 'not_prime', 'Art', 33.3]];
  return [{ Inventory }];
}
